// Extract comment data from webhook payload
const payload = $input.first().json;

return {
  commentId: payload.commentId || payload.id,
  postId: payload.postId || payload.post_id,
  postTitle: payload.postTitle || payload.post_title,
  postUrl: payload.postUrl || payload.post_url,
  authorId: payload.authorId || payload.author_id,
  authorName: payload.authorName || payload.author_name || 'Anonymous',
  authorEmail: payload.authorEmail || payload.author_email,
  commentText: payload.commentText || payload.comment || payload.text,
  parentCommentId: payload.parentCommentId || payload.parent_id || null,
  receivedAt: new Date().toISOString(),
  status: 'pending_moderation'
};

// Spam detection logic
const comment = $json.commentText || '';
const authorName = $json.authorName || '';
const authorEmail = $json.authorEmail || '';

let spamScore = 0;
let spamReasons = [];

// Check for spam indicators
const spamKeywords = ['viagra', 'casino', 'poker', 'lottery', 'click here', 'buy now', 'limited offer', 'earn money fast'];
const suspiciousPatterns = [
  /https?:\/\/[^\s]+/gi,  // Multiple URLs
  /(.)\1{4,}/gi,          // Repeated characters
  /[A-Z]{10,}/g           // Excessive caps
];

// Keyword check
spamKeywords.forEach(keyword => {
  if (comment.toLowerCase().includes(keyword)) {
    spamScore += 20;
    spamReasons.push(`Contains spam keyword: ${keyword}`);
  }
});

// URL density check
const urls = comment.match(/https?:\/\/[^\s]+/gi) || [];
if (urls.length > 3) {
  spamScore += 30;
  spamReasons.push(`Too many URLs: ${urls.length}`);
}

// Pattern checks
suspiciousPatterns.forEach((pattern, idx) => {
  if (pattern.test(comment)) {
    spamScore += 15;
    if (idx === 1) spamReasons.push('Repeated characters detected');
    if (idx === 2) spamReasons.push('Excessive capitalization');
  }
});

// Short comment with URL
if (comment.length < 20 && urls.length > 0) {
  spamScore += 25;
  spamReasons.push('Very short comment with URL');
}

// Suspicious email patterns
if (authorEmail && (authorEmail.includes('.ru') || authorEmail.includes('.cn') || authorEmail.match(/[0-9]{8,}/))) {
  spamScore += 10;
  spamReasons.push('Suspicious email pattern');
}

// Determine status
let status = 'approved';
let action = 'notify';

if (spamScore >= 50) {
  status = 'spam';
  action = 'block';
} else if (spamScore >= 25) {
  status = 'requires_review';
  action = 'review';
}

return {
  ...$json,
  spamScore: spamScore,
  spamReasons: spamReasons,
  status: status,
  action: action,
  checkedAt: new Date().toISOString()
};

// Prepare notification data
const comment = $input.first().json;
const author = $input.last().json;

if (!author || !author.email) {
  return {
    skip: true,
    reason: 'No notification email found or notifications disabled'
  };
}

return {
  recipientEmail: author.email,
  recipientName: author.user_id,
  postTitle: comment.postTitle || author.post_title,
  postUrl: comment.postUrl || author.post_url,
  commentAuthor: comment.authorName,
  commentText: comment.commentText,
  commentId: comment.commentId,
  requiresReview: comment.action === 'review',
  notificationType: 'new_comment'
};

